// spec: specs/events.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

const EVENT_PATH = '/events/087e8dd0-3043-4e55-b182-c2b646c7b7f8';
const EVENT_URL_RE = /\/events\/087e8dd0-3043-4e55-b182-c2b646c7b7f8$/;

test.describe('רכישת כרטיס לאירוע', () => {
  test('פרטי הקונה: שם וטלפון לקריאה בלבד, אימייל ריק/לא תקין — "כתובת האימייל אינה תקינה" @android @prod-safe #6a86f7bc4808', async ({ page }) => {
    // 1. /wallet — היתרה הזמינה; אם ≥ ₪11,100 מדלגים
    await page.goto('/wallet');
    const balanceText = await page.getByTestId('balance-available').innerText();
    const balance = Number(balanceText.replace(/[^\d.]/g, ''));
    test.skip(balance >= 11100, 'баланс client ≥ ₪11,100 — клик купит билет');

    // 2. לפתוח את האירוע; "פרטי הקונה"
    await page.goto(EVENT_PATH);
    await expect(page.getByText('פרטי הקונה', { exact: true })).toBeVisible();
    await expect(page.getByTestId('buyer-name')).toHaveText('יונתן לוי');
    await expect(page.getByTestId('buyer-phone')).toHaveText('050-0000004');
    await expect(page.getByRole('textbox')).toHaveCount(1);
    const email = page.getByRole('textbox', { name: 'אימייל לקבלת הכרטיס' });
    await expect(email).toHaveAttribute('placeholder', 'name@example.com');

    // 3. רדיו "QA VIP", "הוספת כרטיס" × 5 (סה"כ ₪11,100); אימייל ריק → "קניית כרטיס"
    await page.getByRole('radio', { name: 'QA VIP, ₪1,850' }).click();
    for (let i = 0; i < 5; i++) await page.getByRole('button', { name: 'הוספת כרטיס' }).click();
    await expect(page.getByTestId('summary-total')).toHaveText('₪11,100');
    // הסה"כ גבוה מהיתרה — הלחיצה לא יכולה לחייב
    await page.getByRole('button', { name: 'קניית כרטיס' }).click();
    await expect(page.getByText('כתובת האימייל אינה תקינה')).toBeVisible();
    await expect(page).toHaveURL(EVENT_URL_RE);
    await expect(page.getByText('הרכישה בוצעה בהצלחה!')).toHaveCount(0);

    // 4. אימייל "abc" → "קניית כרטיס"
    await email.fill('abc');
    await page.getByRole('button', { name: 'קניית כרטיס' }).click();
    await expect(page.getByText('כתובת האימייל אינה תקינה')).toBeVisible();
    await expect(page).toHaveURL(EVENT_URL_RE);
    await expect(page.getByText('הרכישה בוצעה בהצלחה!')).toHaveCount(0);
  });
});
